from content.authoring import E, J, L, P, Q, R, T

LESSONS = [
L('java-program-skeleton', 'Your First Running Program', 'Write Main.java, compile it, and run its main method.',
  ['Java source is plain text. In this course the file is Main.java and its public class is Main. The names must agree. The compiler javac checks the source and produces Main.class. The java command runs that compiled class; do not pass Main.java to this course’s compiled-run command.',
   'Execution starts in public static void main(String[] args). Braces group the class body and method body. The print statement belongs inside main and ends with a semicolon. For now, keep the entry-point words intact; methods and static will get their own lessons later.',
   'The Code Bench performs compile then run for you. A successful run is not the same as a correct task answer. Check stdout against the requested text. Compiler errors happen before the program can run.'],
  ['Locate the entry point and its statement.', 'Compile and run a correctly named Main class.'],
  E(J('System.out.println("Hello, Java!");'), 'Hello, Java!\n', ['javac checks Main.java.', 'java invokes Main.main.', 'println emits the greeting and a newline.']),
  Q('What exact line is printed? Write only the output, not quotation marks.', J('System.out.println("Ready to build");'), 'Ready to build', 'The quoted text is the argument to println. The quotes delimit the Java String; they are not printed.'),
  R('Describe the two steps between saving Main.java and seeing output.', 'javac compiles the source to a class file; java starts the main method in that class.', ['I distinguish source from compiled bytecode.', 'I name compilation before execution.']),
  P('Print the single line My first Java program. Match spelling and spaces.', J('System.out.println("My first Java program");'), [T('required greeting', '', 'My first Java program\n'), T('repeatability', '', 'My first Java program\n')],
    hints=['Place System.out.println inside main.', 'Keep Main as the public class name.'], rubric=['The statement is inside main.', 'The class name matches Main.java.']),
  diagram={'kind': 'sequence', 'nodes': ['Main.java: source', 'javac: compile', 'Main.class: bytecode', 'java Main: output'], 'edges': [[0,1],[1,2],[2,3]]}),
L('output-and-comments', 'Output, Lines & Comments', 'Make a readable receipt without confusing code with output.',
  ['println prints its argument followed by a line break. print does not add a break. Two print calls can therefore share a line. Use spaces and labels deliberately: a program can run successfully while its output is hard to read.',
   'A // comment ends at the end of its source line. The compiler ignores comments. Use a comment to explain a decision, not to repeat every statement. Text inside double quotes is a String literal, even when it contains symbols that look like code.'],
  ['Choose print versus println for a layout.', 'Use comments without changing program output.'],
  E(J('System.out.print("Ticket: ");\nSystem.out.println("Standard");\n// One item per line.\nSystem.out.println("Total: 300");'), 'Ticket: Standard\nTotal: 300\n', ['print leaves the cursor after the space.', 'println completes the ticket line.', 'The comment does not print.']),
  Q('Write the exact two output lines.', J('System.out.print("A");\nSystem.out.println("B");\nSystem.out.println("C");'), 'AB\nC', 'The first print adds no newline; B completes that line, and C starts the next.'),
  R('Why does commenting out a print statement change output, while adding a comment does not?', 'A comment is ignored by compilation. Commenting out a statement removes that statement from the compiled program.', ['I state that comments are not executed.', 'I distinguish an explanatory comment from disabling a statement.']),
  P('Print a two-line book label: Title: Orbit then Status: Available. Add one useful comment.', J('// Display a readable book label.\nSystem.out.println("Title: Orbit");\nSystem.out.println("Status: Available");'), [T('book label', '', 'Title: Orbit\nStatus: Available\n'), T('second run', '', 'Title: Orbit\nStatus: Available\n')], rubric=['Each field is on its own line.', 'My comment explains the layout or intent.']),
  diagram={'kind':'sequence','nodes':['print("A") → A, no break','println("B") → AB, then break','println("C") → new line C'],'edges':[[0,1],[1,2]]}),
L('problem-decomposition', 'Plan Inputs, Work & Output', 'Design a small request before choosing Java syntax.',
  ['Start with the result the user needs. Then list the inputs that determine it. Processing connects those inputs to the result. For a ticket total, count and unit price are inputs, multiplication is processing, and total is output.',
   'A plan is not yet Java code. Use ordinary words here. Record units and assumptions: a count is a whole number; a fare rate is money per distance unit. State the valid input range, even before you know how to enforce it in Java.',
   'An example tests whether the plan is unambiguous. A valid case, a zero case, and a rejected case expose different mistakes. Later lessons will translate this same input→work→output model into programs.'],
  ['Separate inputs, processing and outputs.', 'State input assumptions and a boundary case.'],
  E('', '', ['Inputs: distance 4 km and rate 8 per km.', 'Work: multiply distance by rate.', 'Output: fare 32.', 'Assumption: distance and rate are nonnegative.'], text='Fare plan: read distance and rate → multiply → display fare.'),
  Q('A ticket plan receives count 4 and unit price 120. Multiply them. What total should be displayed?', '', '480', 'Four tickets at 120 each cost 480. Neither Java input handling nor a condition is needed to write this plan.'),
  R('Plan a rectangular garden’s area without writing Java. Include inputs, work, output, units and invalid inputs.', 'Input width and length in metres. Require nonnegative finite values. Multiply them. Output area in square metres; reject negative or nonnumeric measurements.', ['I name width and length with units.', 'I specify multiplication and area output.', 'I include a zero case and a rejected negative case.']),
  diagram={'kind':'sequence','nodes':['INPUT: count & price','WORK: count × price','OUTPUT: total'],'edges':[[0,1],[1,2]]}),
L('flowchart-symbols', 'Draw a Decision Path', 'Use standard shapes and label every branch.',
  ['Use an oval for start/end, a parallelogram for input/output, a rectangle for processing, and a diamond for a question. Arrows show the order. A diamond needs labeled outcomes, such as yes and no, not an unexplained fork.',
   'This ticket plan accepts count greater than zero. The yes path calculates count × price and displays the total. The no path displays Invalid count. Both paths end. The diagram and walkthrough deliberately use the same count rule.',
   'Draw the chart on paper or describe it in the response box. Do not write Scanner or if syntax for this task. Trace one valid and one invalid count through the arrows to check the plan.'],
  ['Choose the shape for a question or input.', 'Trace both labeled branches to an end.'],
  E('', '', ['Start → read count and price.', 'Question: count > 0?', 'Yes → calculate total → display total → end.', 'No → display Invalid count → end.'], text='The diagram below is the worked flowchart.'),
  Q('Which branch does count 0 take: yes or no?', '', 'no', 'The test is count > 0, not count >= 0. Zero follows no.'),
  R('Describe a flowchart for a nonnegative distance. Name the shapes, label the decision, and include both outcomes.', 'Oval start, input parallelogram, diamond distance >= 0. Yes leads to a processing rectangle for fare and an output parallelogram. No leads to an invalid-distance output. Both lead to an end oval.', ['I name input/output and decision shapes.', 'I label yes and no for distance >= 0.', 'Both paths produce a result and end.']),
  diagram={'kind':'branch','nodes':['Start / read count & price','count > 0?','YES: total = count × price','NO: Invalid count','Display total','End'],'edges':[[0,1],[1,2],[1,3],[2,4],[4,5],[3,5]]}),
L('pseudocode', 'Write Precise Pseudocode', 'Describe order and decisions without language-specific syntax.',
  ['Pseudocode is a readable plan, not a compiler input. Use clear commands such as READ, IF, DISPLAY and END. Indent the steps inside a decision so the reader knows which work is conditional.',
   'Make comparison boundaries explicit. IF count > 0 excludes zero; IF count >= 0 includes it. Name what happens on invalid input. Do not hide required work behind phrases like “process the data.”',
   'Dry-run the plan with a small input table before implementing it. Record the output that each input should produce. That table becomes the program’s acceptance cases later.'],
  ['Write ordered, unambiguous steps.', 'Dry-run valid, zero and invalid inputs.'],
  E('', '', ['READ count and price.', 'IF count > 0: DISPLAY count × price.', 'ELSE: DISPLAY Invalid count.', 'END.'], text='READ count, price\nIF count > 0\n  DISPLAY count * price\nELSE\n  DISPLAY Invalid count\nEND'),
  Q('The worked plan uses count > 0. For count -2 and price 10, what exact output is specified?', '', 'Invalid count', 'The negative count takes the else path. Do not multiply an invalid count.'),
  R('Write pseudocode for an average of two valid numbers. Include reading, calculation and output; give two dry-run cases.', 'READ a and b. SET average to (a + b) / 2. DISPLAY average. Cases: 2 and 4 → 3; 0 and 0 → 0.', ['I read both values before calculating.', 'I group the addition before dividing.', 'I give normal and zero cases with expected outputs.']),
  diagram={'kind':'sequence','nodes':['READ values','CALCULATE with explicit grouping','DISPLAY result','Compare with dry-run table'],'edges':[[0,1],[1,2],[2,3]]}),
L('compiler-diagnostics', 'Repair the First Compiler Error', 'Read location and message, then make the smallest repair.',
  ['A compiler message names a source file, a line and a reason. The first error often causes later errors. Start there, compare punctuation and braces, and compile again before changing anything else.',
   'Syntax errors stop compilation. A valid program can still contain a logic error: printing the wrong text compiles perfectly. Distinguish compiler success, runtime success, and meeting a requirement. The course saves them separately.',
   'For missing semicolons, the compiler may point at the next line because that is where it can no longer parse the preceding statement. Look just above the reported location too.'],
  ['Separate syntax and logic errors.', 'Repair a compiler diagnostic without rewriting working code.'],
  E(J('System.out.println("Fixed");'), 'Fixed\n', ['The semicolon ends the statement.', 'The compiler accepts the method.', 'The requested text appears at runtime.']),
  Q('A program compiles and prints Wrong when its requirement says Ready. Name the error category: syntax or logic.', '', 'logic', 'The code is legal Java but does not meet the output requirement.'),
  R('What is your repair procedure when javac reports several errors?', 'Read the first location and message; inspect that line and the preceding one; make one small repair; compile again; only then test the output.', ['I start with the first compiler error.', 'I recompile after one change.', 'I test requirements after compilation succeeds.']),
  P('Print Ready on one line. Do not treat a successful compile as the full check.', J('System.out.println("Ready");'), [T('requested text', '', 'Ready\n'), T('same program, another run', '', 'Ready\n')]),
  extra_practice=P('Repair the missing semicolon so this program prints Fixed.', J('System.out.println("Fixed");'), [T('after repair', '', 'Fixed\n'), T('after repair again', '', 'Fixed\n')], starter=J('System.out.println("Fixed")'), kind='repair', starter_expected_status='compile_error', hints=['Read the first compiler message.', 'A Java print statement must end with a semicolon.'], rubric=['I repaired the punctuation rather than deleting the print statement.']),
  diagram={'kind':'sequence','nodes':['Compiler diagnostic','First location + preceding line','One repair','Compile again','Run & check requirement'],'edges':[[0,1],[1,2],[2,3],[3,4]]}),
]
